package org.apache.commons.jxpath.ri.model.beans;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.jxpath.AbstractFactory;
import org.apache.commons.jxpath.JXPathAbstractFactoryException;
import org.apache.commons.jxpath.JXPathContext;
import org.apache.commons.jxpath.JXPathInvalidAccessException;
import org.apache.commons.jxpath.XPathException;
import org.apache.commons.jxpath.ri.QName;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.apache.commons.jxpath.ri.model.QName;
import org.apache.commons.jxpath.ri.model.beans.PropertyOwnerPointer;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class NullPropertyPointer_createPath_TriageGen0Test {

    private JXPathContext mockContext;
    private NodePointer mockParent;
    private QName mockQName;
    private Object testValue;

    @Before
    public void setUp() {
        mockContext = mock(JXPathContext.class);
        mockParent = mock(NodePointer.class);
        mockQName = mock(QName.class);
        testValue = new Object();

        // Default behavior for getName() if needed, though it's called on the NullPropertyPointer instance
        // In the provided code, getName() is called on the instance (this), not the parent.
    }

    /**
     * Tests the branch: parent is NullPointer and parent.equals(newParent)
     * This triggers the createBadFactoryException.
     */
    @Test(expected = Exception.class)
    public void testCreatePath_ThrowsExceptionWhenParentIsNullPointerAndEqualsNewParent() {
        // Setup: parent is a NullPointer and newParent is the same instance
        NullPropertyPointer nullPointerParent = spy(new NullPropertyPointer(null));
        // We need to mock the behavior so that parent.equals(newParent) returns true.
        // Since the method uses 'parent' (the field), we rely on the constructor.

        // The code says: if (parent instanceof NullPointer && parent.equals(newParent))
        // So we create a NullPropertyPointer where the internal 'parent' field is itself.
        // However, the constructor takes a NodePointer.

        NullPropertyPointer subject = new NullPropertyPointer(nullPointerParent);
        // Mocking 'parent' field is hard in Java without reflection, 
        // but we can simulate the condition by making newParent return the same object.

        when(nullPointerParent.createPath(mockContext)).thenReturn(nullPointerParent);
        // Since nullPointerParent is a NullPropertyPointer, it is an instance of NullPointer

        // We need to mock context.getFactory() for the exception creation
        when(mockContext.getFactory()).thenReturn(null); 

        subject.createPath(mockContext, testValue);
    }

    /**
     * Tests the branch: newParent is a PropertyOwnerPointer
     */
    @Test
    public void testCreatePath_WhenNewParentIsPropertyOwnerPointer() {
        PropertyOwnerPointer mockPop = mock(PropertyOwnerPointer.class);
        NodePointer mockChildPointer = mock(NodePointer.class);

        NullPropertyPointer subject = spy(new NullPropertyPointer(mockParent));

        when(mockParent.createPath(mockContext)).thenReturn(mockPop);
        when(mockPop.getPropertyPointer()).thenReturn(mockChildPointer);
        // The method then calls: return newParent.createChild(context, getName(), index, value);
        // But newParent was reassigned to pop.getPropertyPointer()

        // Note: getName(), index are members of the current instance (subject)
        // We need to ensure the subject has a name to avoid NPE if getName() is used.
        subject.setPropertyName("testProp");

        // Mock the createChild call on the result of getPropertyPointer()
        when(mockChildPointer.createChild(eq(mockContext), any(QName.class), anyInt(), eq(testValue)))
                .thenReturn(mockChildPointer);

        NodePointer result = subject.createPath(mockContext, testValue);

        assertEquals(mockChildPointer, result);
        verify(mockPop).getPropertyPointer();
    }

    /**
     * Tests the standard branch: newParent is a normal NodePointer
     */
    @Test
    public void testCreatePath_StandardPath() {
        NodePointer mockNewParent = mock(NodePointer.class);
        NodePointer mockResult = mock(NodePointer.class);

        NullPropertyPointer subject = spy(new NullPropertyPointer(mockParent));
        subject.setPropertyName("testProp");

        when(mockParent.createPath(mockContext)).thenReturn(mockNewParent);
        // Mock createChild on the newParent
        when(mockNewParent.createChild(eq(mockContext), any(QName.class), anyInt(), eq(testValue)))
                .thenReturn(mockResult);

        NodePointer result = subject.createPath(mockContext, testValue);

        assertEquals(mockResult, result);
        verify(mockNewParent).createChild(eq(mockContext), any(QName.class), anyInt(), eq(testValue));
    }
}
